#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const long long INF = 4e18;

struct Point {
    long long u, v;
};

int n;
vector<Point> pts;
long long min_u, max_u, min_v, max_v;

bool check(long long D) {
    if (max_u - min_u <= D && max_v - min_v <= D) {
        return true;
    }

    // Os 4 cantos para o primeiro quadrado:
    // 0: [min_u, min_u + D] x [min_v, min_v + D]
    // 1: [min_u, min_u + D] x [max_v - D, max_v]
    // 2: [max_u - D, max_u] x [min_v, min_v + D]
    // 3: [max_u - D, max_u] x [max_v - D, max_v]

    long long c_u_min[4] = {min_u, min_u, max_u - D, max_u - D};
    long long c_u_max[4] = {min_u + D, min_u + D, max_u, max_u};
    long long c_v_min[4] = {min_v, max_v - D, min_v, max_v - D};
    long long c_v_max[4] = {min_v + D, max_v, min_v + D, max_v};

    long long rem_min_u[4], rem_max_u[4], rem_min_v[4], rem_max_v[4];
    for (int k = 0; k < 4; ++k) {
        rem_min_u[k] = INF;
        rem_max_u[k] = -INF;
        rem_min_v[k] = INF;
        rem_max_v[k] = -INF;
    }

    for (int i = 0; i < n; ++i) {
        long long u = pts[i].u;
        long long v = pts[i].v;

        for (int k = 0; k < 4; ++k) {
            // Se o ponto não está coberto pelo quadrado k
            if (u < c_u_min[k] || u > c_u_max[k] || v < c_v_min[k] || v > c_v_max[k]) {
                if (u < rem_min_u[k]) rem_min_u[k] = u;
                if (u > rem_max_u[k]) rem_max_u[k] = u;
                if (v < rem_min_v[k]) rem_min_v[k] = v;
                if (v > rem_max_v[k]) rem_max_v[k] = v;
            }
        }
    }

    for (int k = 0; k < 4; ++k) {
        if (rem_min_u[k] == INF) {
            // Todos os pontos foram cobertos pelo primeiro quadrado
            return true;
        }
        if (rem_max_u[k] - rem_min_u[k] <= D && rem_max_v[k] - rem_min_v[k] <= D) {
            return true;
        }
    }

    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n)) return 0;

    vector<long long> X(n), Y(n);
    for (int i = 0; i < n; ++i) {
        cin >> X[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> Y[i];
    }

    pts.resize(n);
    min_u = INF; max_u = -INF;
    min_v = INF; max_v = -INF;

    for (int i = 0; i < n; ++i) {
        pts[i].u = X[i] + Y[i];
        pts[i].v = X[i] - Y[i];
        min_u = min(min_u, pts[i].u);
        max_u = max(max_u, pts[i].u);
        min_v = min(min_v, pts[i].v);
        max_v = max(max_v, pts[i].v);
    }

    long long low = 0, high = 2000000000LL;
    long long ans = high;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";

    return 0;
}
